(()=>{function styleRequirements(){const active=!!document.querySelector('.req-overview');document.body.classList.toggle('req-d-style',active);if(!active)return;document.querySelectorAll('[data-other-drawer]').forEach(card=>{card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label','查看工作单：'+card.querySelector('.work-name').textContent);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();card.click()}}});const scroller=document.querySelector('.gantt-scroll');if(scroller){scroller.tabIndex=0;scroller.setAttribute('role','region');scroller.setAttribute('aria-label','按日工单时间线，可横向滚动；左侧工单信息固定')}}const previousRender=render;render=function(){previousRender();styleRequirements()};styleRequirements()})();

